<template><section class="ops-panel"><div class="ops-toolbar"><h2>员工身份申请与恢复</h2><el-button size="small" @click="load">刷新</el-button></div><p class="ops-muted">申请人自行设置验证器和密码。身份治理人员只确认身份，不接收密码、验证器密钥或恢复码。</p><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table :data="rows" v-loading="loading"><el-table-column prop="username" label="员工" /><el-table-column label="申请类型"><template slot-scope="s">{{ s.row.kind === 'RECOVER' ? '恢复身份' : '新员工激活' }}</template></el-table-column><el-table-column prop="status" label="状态" /><el-table-column prop="expiresAt" label="有效期至" min-width="170" /><el-table-column label="操作"><template slot-scope="s"><el-button v-if="s.row.status === 'PENDING' && can('iam.request') && s.row.employeeId !== employeeId" type="text" :disabled="busy" @click="process(s.row,'endorse')">确认身份</el-button><el-button v-if="s.row.status === 'ENDORSED' && can('iam.approve') && s.row.employeeId !== employeeId && s.row.requesterId !== employeeId" type="text" :disabled="busy" @click="process(s.row,'approve')">批准生效</el-button></template></el-table-column></el-table></section></template>
<script>
import { platformRequest } from '@/apis/platform';
import { hasPermission } from '@/security/session';
export default { data() { return { rows:[],loading:false,busy:false,error:'' }; }, computed:{employeeId(){return this.$store.state.userInfo.employeeId;}},created(){this.load();},methods:{can(permission){return hasPermission(this.$store.state.userInfo,permission);},async load(){this.loading=true;this.error='';try{this.rows=await platformRequest('GET','/ops/iam/identity-requests');}catch(error){this.error=error.message;}finally{this.loading=false;}},async process(row,action){if(this.busy)return;try{await this.$confirm(`确认已核实 ${row.username} 的身份申请？`,'处理身份申请',{type:'warning'});}catch(_){return;}this.busy=true;try{await platformRequest('POST',`/ops/iam/identity-requests/${encodeURIComponent(row.id)}/${action}`);await this.load();this.$emit('updated');}catch(error){this.$message.error(error.message);}finally{this.busy=false;}}} };
</script>
